WITH with_latest AS (SELECT s.*, x.employee_level FROM departments s LEFT JOIN LATERAL (SELECT c.level AS employee_level FROM employees c WHERE c.dept_id = s.id ORDER BY c.salary DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT CASE WHEN budget >= 4091000 THEN 'LARGE' ELSE 'SMALL' END AS budget_tier, location, SIZE(COLLECT_SET(location)) AS num_locations, AVG(budget) FILTER (WHERE dept_name = 'HR') AS hr_avg_budget, AVG(budget) FILTER (WHERE dept_name = 'HR') AS hr_avg_budget_2, COUNT_IF(location = 'Tokyo') AS tokyo_events, STDDEV_SAMP(budget) AS budget_stddev, SUM(CASE WHEN dept_name = 'Engineering' THEN budget ELSE 0 END) AS engineering_budget FROM with_latest GROUP BY CASE WHEN budget >= 4091000 THEN 'LARGE' ELSE 'SMALL' END, location ORDER BY budget_stddev DESC NULLS FIRST
